          var val = o === '__custom__' ? '__custom__' : o;
          var text = o === '__custom__' ? '自定义…' : o;
          var sel = (isCustom ? (o === '__custom__') : (o === v)) ? ' selected' : '';
          return '<option value="' + esc(val) + '"' + sel + '>' + esc(text) + '</option>';
        }).join('') + '</select>' +
        (f.custom ? '<input type="text" class="rp-wz-custom" id="' + id + '-custom" placeholder="自己写一个" value="' +
