    });
    if (!blocks) blocks = '<p class="rp-wz-tip">还没有填任何内容。回到前面的步骤填几项。</p>';
    var missing = [];
    STEPS.forEach(function (s) {
      (s.fields || []).forEach(function (f) {
        if (f.req && (!data[f.k] || data[f.k] === '__custom__')) missing.push(f.label);
      });
    });
    var warn = missing.length
      ? '<p class="rp-wz-tip">还差必填项：' + esc(missing.join('、')) + '。留着也能导出，但下游会当作未定。</p>'
      : '';
    return '<div class="rp-wz-sum">' + warn + blocks +
      '<div class="rp-wz-out" id="rp-wz-md">' + esc(markdown()) + '</div>' +
      '<p class="rp-wz-tip" id="rp-wz-copy-tip">' + esc(OUTRO) + '</p></div>';
  }

  function render() {
    var s = STEPS[step];
    var body = s.kind === 'lore' ? renderLore(s)
      : s.kind === 'form' ? (s.fields || []).map(renderField).join('')
