      '<div class="rp-wz-nav">' +
      '<button type="button" class="rp-wz-btn" data-nav="-1"' + (step === 0 ? ' disabled' : '') + '>← 上一步</button>' +
      (s.kind === 'summary'
        ? '<button type="button" class="rp-wz-btn is-primary" data-copy="1">复制档案</button>'
        : '<button type="button" class="rp-wz-btn is-primary" data-nav="1">下一步 →</button>') +
