        collect(s);
      });
    });
    Array.prototype.forEach.call(ROOT.querySelectorAll('[data-copy]'), function (el) {
      el.addEventListener('click', function () { collect(s); copy(markdown()); });
    });
  }

  function collect(s) {
    if (s.kind !== 'form') return;
    (s.fields || []).forEach(function (f) {
      var el = document.getElementById('rp-wz-f-' + f.k);
      if (!el) return;
      var v = el.value;
      if (f.type === 'select' && v === '__custom__') {
        var c = document.getElementById('rp-wz-f-' + f.k + '-custom');
        v = c ? c.value.trim() : '';
      }
      if (v) data[f.k] = v; else delete data[f.k];
    });
    save(STORE_DATA, data);
  }

  function go(next) {
    if (next < 0) next = 0;
    if (next > STEPS.length - 1) next = STEPS.length - 1;
    step = next;
    save(STORE_STEP, step);
    render();
  }

  function copy(text) {
    var tip = document.getElementById('rp-wz-copy-tip');
    function ok() { if (tip) { tip.textContent = '已复制，去聊天里粘贴。'; tip.classList.add('is-ok'); } }
    function fallback() {
      var ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.left = '-9999px';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); ok(); } catch (e) { if (tip) tip.textContent = '复制失败，请手动选中上面的文本。'; }
      document.body.removeChild(ta);
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(ok, fallback);
    } else { fallback(); }
  }

  prefillFromDollar1();
  if (step > STEPS.length - 1) step = 0;
  render();
})();
</script>
